import React from 'react'
import { useAuth } from '../../contexts/AuthContext'
import { useNotebook } from '../../contexts/NotebookContext'
import ThreePanelLayout from '../Layout/ThreePanelLayout'
import UploadZone from '../common/UploadZone'
import LoadingSpinner from '../common/LoadingSpinner'
import { LogOut, Upload } from 'lucide-react'

const Dashboard = () => {
  const { user, logout } = useAuth()
  const { currentSession, isLoading, clearSession } = useNotebook()

  const handleLogout = () => {
    logout()
    clearSession()
  }

  if (isLoading) {
    return <LoadingSpinner message="Loading your workspace..." />
  }

  if (!currentSession) {
    return (
      <div className="min-h-screen bg-background">
        {/* Header */}
        <header className="border-b border-border bg-card">
          <div className="container mx-auto px-4 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-primary/10 rounded-lg">
                  <div className="w-6 h-6 bg-primary rounded-sm" />
                </div>
                <div>
                  <h1 className="text-xl font-bold text-foreground">AutoVizAI 2.0</h1>
                  <p className="text-sm text-muted-foreground">Welcome, {user?.username}</p>
                </div>
              </div>
              
              <button
                onClick={handleLogout}
                className="flex items-center gap-2 px-4 py-2 text-sm text-muted-foreground hover:text-foreground hover:bg-muted rounded-lg transition-colors"
              >
                <LogOut className="w-4 h-4" />
                Logout
              </button>
            </div>
          </div>
        </header>

        {/* Main Content */}
        <main className="container mx-auto px-4 py-12">
          <UploadZone />
        </main>
      </div>
    )
  }

  return <ThreePanelLayout />
}

export default Dashboard