import React from 'react'
import { useNotebook } from '../../contexts/NotebookContext'
import { Box, Type, Hash, Calendar, List, Info } from 'lucide-react'

const VariablesPanel = () => {
  const { liveVariables } = useNotebook()

  if (!liveVariables || liveVariables.length === 0) {
    return (
      <div className="p-8 text-center text-muted-foreground">
        <Box className="w-8 h-8 mx-auto mb-3 opacity-50" />
        <p>No active variables in memory.</p>
        <p className="text-xs mt-1">Run code cells to create variables.</p>
      </div>
    )
  }

  const getIconForType = (type) => {
    if (!type) return <Box className="w-4 h-4 text-gray-500" />
    const t = type.toLowerCase()
    if (t.includes('int') || t.includes('float') || t.includes('number')) return <Hash className="w-4 h-4 text-blue-500" />
    if (t.includes('str')) return <Type className="w-4 h-4 text-green-500" />
    if (t.includes('date') || t.includes('time')) return <Calendar className="w-4 h-4 text-orange-500" />
    if (t.includes('list') || t.includes('dict') || t.includes('array')) return <List className="w-4 h-4 text-purple-500" />
    return <Box className="w-4 h-4 text-gray-500" />
  }

  return (
    <div className="p-4 space-y-3">
      {liveVariables.map((variable, index) => (
        <div key={index} className="bg-card border border-border rounded-lg p-3 hover:shadow-sm transition-shadow">
          <div className="flex items-start justify-between mb-1">
            <div className="flex items-center gap-2">
              {getIconForType(variable.type)}
              <span className="font-mono font-medium text-sm">{variable.name}</span>
            </div>
            <span className="text-xs px-2 py-0.5 bg-muted rounded text-muted-foreground font-mono">
              {variable.type}
            </span>
          </div>

          <div className="pl-6">
            <div className="text-xs text-muted-foreground mb-1">Value:</div>
            <div className="font-mono text-xs bg-muted/50 p-2 rounded overflow-x-auto whitespace-pre-wrap max-h-20">
              {variable.value_preview || variable.value || 'N/A'}
            </div>
            {variable.info && (
              <div className="mt-2 text-xs text-muted-foreground border-t border-border/50 pt-1 flex items-center gap-1">
                <Info className="w-3 h-3" />
                {variable.info}
              </div>
            )}
          </div>
        </div>
      ))}
    </div>
  )
}

export default VariablesPanel